mapper.select:
SELECT u.id, u.username, u.real_name, u.user_type, u.student_no, u.staff_no, u.class_id, u.major, u.status, u.create_time, c.class_name FROM sys_user u LEFT JOIN sys_class c ON u.class_id = c.id
AND u.real_name LIKE CONCAT('%', #{realName}, '%')
AND (u.student_no LIKE CONCAT('%', #{userId}, '%') OR u.staff_no LIKE CONCAT('%', #{userId}, '%'))
AND u.user_type = #{userType}
AND u.status = #{status}
AND u.class_id = #{classId}
ORDER BY u.create_time DESC
